const std = @import("std");
const assert = std.debug.assert;
const math = std.math;
const Allocator = std.mem.Allocator;

pub const BelugeError = error{
    OutOfBounds,
    DimensionMismatch,
    InvalidDataType,
    AllocationFailed,
    InvalidKernelOperation,
};

pub const DataType = enum {
    f16,
    f32,
    f64,
    i32,
    i64,
    SpikeEvent,
};

pub const Spike = struct {
    timestamp: u64,
    neuron_id: u32,
    saliency: f32,
};

pub const Tensor = struct {
    allocator: *Allocator,
    data_type: DataType,
    shape: []const usize,
    data: []u8,

    pub fn init(allocator: *Allocator, data_type: DataType, shape: []const usize) !*Tensor {
        const self = try allocator.create(Tensor);
        var total_elements: usize = 1;
        for (shape) |dim| {
            total_elements *= dim;
        }

        const type_size = @sizeOf(switch (data_type) {
            .f16 => f16,
            .f32 => f32,
            .f64 => f64,
            .i32 => i32,
            .i64 => i64,
            .SpikeEvent => Spike,
        });

        self.* = .{
            .allocator = allocator,
            .data_type = data_type,
            .shape = try allocator.dupe(usize, shape),
            .data = try allocator.alloc(u8, total_elements * type_size),
        };
        return self;
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.shape);
        self.allocator.free(self.data);
        self.allocator.destroy(self);
    }

    pub fn getAs(self: *Tensor, comptime T: type) ![]T {
        if (@sizeOf(T) != @sizeOf(switch (self.data_type) {
            .f16 => f16,
            .f32 => f32,
            .f64 => f64,
            .i32 => i32,
            .i64 => i64,
            .SpikeEvent => Spike,
        })) {
            return BelugeError.InvalidDataType;
        }
        return @ptrCast([*]T, self.data.ptr)[0..self.data.len / @sizeOf(T)];
    }

    pub fn print(self: *Tensor) !void {
        const stdout = std.io.getStdOut().writer();
        try stdout.print("Tensor(shape={any}, dtype={s})\n", .{ self.shape, @tagName(self.data_type) });
        switch (self.data_type) {
            .f32 => {
                const slice = try self.getAs(f32);
                try stdout.print("{any}\n", .{slice});
            },
            .SpikeEvent => {
                const slice = try self.getAs(Spike);
                for (slice) |spike| {
                    try stdout.print("Spike(t={}, id={}, salience={})\n", .{ spike.timestamp, spike.neuron_id, spike.saliency });
                }
            },
            else => {
                try stdout.print("Printing for this dtype is not implemented.\n", .{});
            },
        }
    }
};

pub const OperatorCore = struct {
    allocator: *Allocator,

    pub fn convolve_1d(input: *Tensor, kernel: *Tensor, output: *Tensor) !void {
        if (input.data_type != .f32 or kernel.data_type != .f32 or output.data_type != .f32) {
            return BelugeError.InvalidDataType;
        }
        if (input.shape.len != 1 or kernel.shape.len != 1 or output.shape.len != 1) {
            return BelugeError.DimensionMismatch;
        }

        const input_slice = try input.getAs(f32);
        const kernel_slice = try kernel.getAs(f32);
        const output_slice = try output.getAs(f32);

        const input_len = input_slice.len;
        const kernel_len = kernel_slice.len;
        const output_len = output_slice.len;

        if (output_len != input_len - kernel_len + 1) {
            return BelugeError.DimensionMismatch;
        }

        for (0..output_len) |i| {
            var sum: f32 = 0.0;
            for (0..kernel_len) |j| {
                sum += input_slice[i + j] * kernel_slice[j];
            }
            output_slice[i] = sum;
        }
    }

    pub fn GIF_integrate(spikes: []const Spike, weights: *Tensor, neuron_states: *Tensor, threshold: f32, decay: f32) !*Tensor {
        const weight_slice = try weights.getAs(f32);
        const state_slice = try neuron_states.getAs(f32);
        const num_neurons = state_slice.len;

        var output_spikes = std.ArrayList(Spike).init(neuron_states.allocator);
        errdefer output_spikes.deinit();

        for (0..num_neurons) |i| {
            state_slice[i] *= decay;
        }

        for (spikes) |spike| {
            const neuron_id = spike.neuron_id;
            if (neuron_id >= num_neurons) continue;

            for (0..num_neurons) |j| {
                state_slice[j] += spike.saliency * weight_slice[neuron_id * num_neurons + j];
            }
        }

        for (0..num_neurons) |i| {
            if (state_slice[i] > threshold) {
                try output_spikes.append(.{
                    .timestamp = spikes[0].timestamp + 1, 
                    .neuron_id = @intCast(u32, i),
                    .saliency = state_slice[i] - threshold,
                });
                state_slice[i] = 0.0;
            }
        }

        var out_tensor = try Tensor.init(neuron_states.allocator, .SpikeEvent, &[_]usize{output_spikes.items.len});
        @memcpy(out_tensor.data.ptr, output_spikes.items.ptr, output_spikes.items.len * @sizeOf(Spike));

        return out_tensor;
    }
};


