const std = @import("std");
const beluge = @import("beluge.zig");
const Allocator = std.mem.Allocator;

const log = std.log.scoped(.jaide_env);

pub const JaideEnvironment = struct {
    allocator: Allocator,
    operator_core: beluge.OperatorCore,

    const MAX_TENSORS = 1024;
    tensors: [MAX_TENSORS]?*beluge.Tensor,
    tensor_count: usize,

    pub fn init(heap_allocator: Allocator) JaideEnvironment {
        return JaideEnvironment{
            .allocator = heap_allocator,
            .operator_core = beluge.OperatorCore{ .allocator = &heap_allocator },
            .tensors = [_]?*beluge.Tensor{null} ** MAX_TENSORS,
            .tensor_count = 0,
        };
    }

    pub fn deinit(self: *JaideEnvironment) void {
        log.info("Deinitializing Jaide Environment, freeing {d} tensors.", .{self.tensor_count});
        for (self.tensors) |maybe_tensor| {
            if (maybe_tensor) |tensor| {
                tensor.deinit();
            }
        }
        log.info("All tensors freed.", .{});
    }

    pub fn createTensor(self: *JaideEnvironment, data_type: beluge.DataType, shape: []const usize) !usize {
        if (self.tensor_count >= MAX_TENSORS) {
            log.err("Maximum tensor limit reached.", .{});
            return error.TooManyTensors;
        }

        const tensor = try beluge.Tensor.init(&self.allocator, data_type, shape);

        var handle: usize = 0;
        while (handle < MAX_TENSORS) : (handle += 1) {
            if (self.tensors[handle] == null) {
                self.tensors[handle] = tensor;
                self.tensor_count += 1;
                log.debug("Created tensor with handle {d}", .{handle});
                return handle;
            }
        }

        unreachable;
    }

    pub fn getTensor(self: *JaideEnvironment, handle: usize) !*beluge.Tensor {
        if (handle >= MAX_TENSORS or self.tensors[handle] == null) {
            return error.InvalidTensorHandle;
        }
        return self.tensors[handle].?;
    }

    pub fn releaseTensor(self: *JaideEnvironment, handle: usize) !void {
        if (handle >= MAX_TENSORS or self.tensors[handle] == null) {
            return error.InvalidTensorHandle;
        }
        const tensor = self.tensors[handle].?;
        tensor.deinit();
        self.tensors[handle] = null;
        self.tensor_count -= 1;
        log.debug("Released tensor with handle {d}", .{handle});
    }

    pub fn executeGIF(self: *JaideEnvironment, spike_handle: usize, weights_handle: usize, state_handle: usize, threshold: f32, decay: f32) !usize {
        const spike_tensor = try self.getTensor(spike_handle);
        const weights_tensor = try self.getTensor(weights_handle);
        const state_tensor = try self.getTensor(state_handle);

        const spike_slice = try spike_tensor.getAs(beluge.Spike);

        const output_spike_tensor = try self.operator_core.GIF_integrate(spike_slice, weights_tensor, state_tensor, threshold, decay);

        var out_handle: usize = 0;
        while (out_handle < MAX_TENSORS) : (out_handle += 1) {
            if (self.tensors[out_handle] == null) {
                self.tensors[out_handle] = output_spike_tensor;
                self.tensor_count += 1;
                return out_handle;
            }
        }

        unreachable;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var env = JaideEnvironment.init(allocator);
    defer env.deinit();

    const stdout = std.io.getStdOut().writer();
    try stdout.print("Jaide Zig Runtime Environment Initialized.\n", .{});

    const shape = &[_]usize{10};
    const tensor_handle = try env.createTensor(.f32, shape);
    defer env.releaseTensor(tensor_handle) catch {};

    const tensor = try env.getTensor(tensor_handle);
    const data = try tensor.getAs(f32);
    for (data) |*v, i| {
        v.* = @intToFloat(f32, i);
    }

    try tensor.print();

    try stdout.print("Jaide Zig Runtime Test Complete.\n", .{});
}


