            if gate == 'cx':
                circuit['operations'].append({'gate': 'cx', 'control': q1, 'target': q2})
            elif gate == 'cz':
                circuit['operations'].append({'gate': 'cz', 'control': q1, 'target': q2})
            else:
                angle = np.random.uniform(0, 2 * np.pi)
                circuit['operations'].append({'gate': gate, 'qubit': q1, 'angle': angle})

        circuit['operations'].append({'gate': 'measure', 'qubits': list(range(num_qubits)), 'cregs': list(range(num_qubits))})
        return circuit

    def submit_job(self, circuit, shots=8192):
        if not self.connection_established:
            raise ConnectionError("Not connected to IBM Quantum backend.")

