class SpikeTimeEncoder:
    def __init__(self, output_neurons, time_steps):
        self.output_neurons = output_neurons
        self.time_steps = time_steps
        self.char_map = {chr(i): i for i in range(256)} # Simple ASCII map

        # Initialize Lorenz Attractor parameters
        self.sigma = 10.0
        self.rho = 28.0
        self.beta = 8.0 / 3.0
        self.dt = 0.01

        # Use the easter egg seed for the initial state
        self.initial_state, _ = get_lorenz_attractor_seed()

        print("SpikeTimeEncoder initialized with Lorenz attractor dynamics.")
        print(f"Initial state seeded by location-temporal anchor: {self.initial_state}")

    def _lorenz_step(self, state):
        x, y, z = state
        dx = self.sigma * (y - x)
        dy = x * (self.rho - z) - y
        dz = x * y - self.beta * z
        return state + np.array([dx, dy, dz]) * self.dt

    def _generate_chaotic_basis(self, num_chars):
        # Generate a sequence of states from the Lorenz attractor
        states = np.zeros((num_chars, 3))
        states[0] = self.initial_state
        for i in range(1, num_chars):
            states[i] = self._lorenz_step(states[i-1])
        return states

    def encode(self, text: str):
        # Generates a list of spike events (time, neuron_id)
        if not text:
            return np.array([])

        char_basis = self._generate_chaotic_basis(len(self.char_map))

        # Each character's spike pattern is determined by the attractor's state
        spikes = []
        current_time = 0

        for char in text:
            if char not in self.char_map:
                continue

            char_index = self.char_map[char]
            state = char_basis[char_index]

            # The state [x, y, z] determines the spike properties
            # Map x, y, z to neuron_id, number_of_spikes, and time_delta

            # Neuron ID is based on the 'x' component, scaled to neuron range
            neuron_id_base = int( (state[0] + 40) / 80 * self.output_neurons ) % self.output_neurons

            # Number of spikes is based on the 'y' component (saliency)
            num_spikes = int( (state[1] + 40) / 80 * 5) + 1

            # Time delay between spikes is based on 'z'
            time_delta = max(1, int(state[2] / 50 * (self.time_steps / len(text)) / num_spikes))

            for i in range(num_spikes):
                neuron_id = (neuron_id_base + i*5) % self.output_neurons # Spread spikes
                saliency = (state[1] / 40.0) # Map y-coord to saliency
                spikes.append([current_time, neuron_id, saliency])
                current_time += time_delta

        # Ensure total time does not exceed limit
        spike_array = np.array(spikes)
        if spike_array.shape[0] > 0:
            spike_array[:, 0] = (spike_array[:, 0] / np.max(spike_array[:, 0])) * (self.time_steps - 1)

        return spike_array.astype({'0': np.uint64, '1': np.uint32, '2': np.float32})


