# --- Custom SNN Components (No external libraries) ---

class GeneralizedIntegrateAndFireNeuron:
    def __init__(self, num_neurons, decay=0.9, threshold=1.0):
        self.potential = np.zeros(num_neurons, dtype=np.float32)
        self.decay = decay
        self.threshold = threshold
        self.num_neurons = num_neurons

    def step(self, input_current):
        self.potential = self.potential * self.decay + input_current
        spikes = (self.potential >= self.threshold).astype(np.float32)
        saliency = (self.potential - self.threshold) * spikes
        self.potential = self.potential * (1.0 - spikes) # Reset potential
        return spikes, saliency

