    def __init__(self, input_dim, output_dim, kernel_size):
        self.input_dim = input_dim
        self.output_dim = output_dim
        self.kernel_size = kernel_size

        # Initialize weights using a Glorot-like scheme
        limit = np.sqrt(6 / (input_dim + output_dim))
        self.weights = np.random.uniform(-limit, limit, (input_dim, output_dim)).astype(np.float32)

        self.neurons = GeneralizedIntegrateAndFireNeuron(output_dim)

    def __call__(self, spike_train):
        # spike_train is a dict {time: (neuron_ids, saliencies)}
        output_current = np.zeros((max(spike_train.keys()) + 1, self.output_dim), dtype=np.float32)

        for t, (neuron_ids, saliencies) in spike_train.items():
            if len(neuron_ids) == 0:
